<template>
  <div class="contacts-container">
    <div class="contacts-header">
      <h2>通讯录</h2>
      <el-button type="primary" @click="openCreateContactDialog">
        <el-icon><Plus /></el-icon> 新建联系人
      </el-button>
    </div>
    
    <div class="contacts-filter">
      <el-select v-model="departmentFilter" placeholder="部门" class="filter-item" disabled>
        <el-option label="实验室" value="lab" />
      </el-select>
      <el-input
        v-model="searchKeyword"
        placeholder="搜索联系人"
        prefix-icon="Search"
        class="filter-item"
      />
    </div>
    
    <div class="contacts-content">
      <el-table :data="filteredContacts" style="width: 100%">
        <el-table-column label="头像" width="80">
          <template #default="{ row }">
            <el-avatar :size="40">{{ row.name.charAt(0) }}</el-avatar>
          </template>
        </el-table-column>
        <el-table-column prop="name" label="姓名" width="100" />
        <el-table-column prop="department" label="部门" width="100">
          <template #default="{ row }">
            <el-tag>{{ getDepartmentText(row.department) }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="position" label="职位" width="120" />
        <el-table-column prop="email" label="邮箱" />
        <el-table-column prop="phone" label="电话" width="120" />
        <el-table-column label="操作" width="200" fixed="right">
          <template #default="{ row }">
            <div class="action-buttons">
              <el-button size="small" type="primary" link @click="viewContact(row)">查看</el-button>
              <el-button size="small" type="primary" link @click="editContact(row)">编辑</el-button>
              <el-button size="small" type="danger" link @click="deleteContact(row.id)">删除</el-button>
            </div>
          </template>
        </el-table-column>
      </el-table>
      <div v-if="filteredContacts.length === 0" class="empty-table">
        <el-icon class="empty-icon"><User /></el-icon>
        <p>暂无联系人</p>
      </div>
    </div>
    
    <!-- 新建联系人对话框 -->
    <el-dialog
      v-model="createContactVisible"
      :title="isEditing ? '编辑联系人' : '新建联系人'"
      width="500px"
    >
      <el-form :model="newContact" label-width="80px">
        <el-form-item label="姓名" required>
          <el-input v-model="newContact.name" placeholder="请输入姓名" />
        </el-form-item>
        <el-form-item label="部门" required>
          <el-select v-model="newContact.department" placeholder="请选择部门" disabled>
            <el-option label="实验室" value="lab" />
          </el-select>
        </el-form-item>
        <el-form-item label="职位" required>
          <el-input v-model="newContact.position" placeholder="请输入职位" />
        </el-form-item>
        <el-form-item label="邮箱" required>
          <el-input v-model="newContact.email" placeholder="请输入邮箱" />
        </el-form-item>
        <el-form-item label="电话" required>
          <el-input v-model="newContact.phone" placeholder="请输入电话" />
        </el-form-item>
        <el-form-item label="备注">
          <el-input
            v-model="newContact.remark"
            type="textarea"
            :rows="3"
            placeholder="请输入备注"
          />
        </el-form-item>
      </el-form>
      <template #footer>
        <span class="dialog-footer">
          <el-button @click="createContactVisible = false">取消</el-button>
          <el-button type="primary" @click="saveContact">保存</el-button>
        </span>
      </template>
    </el-dialog>
    
    <!-- 联系人详情对话框 -->
    <el-dialog
      v-model="viewContactVisible"
      :title="selectedContact?.name || '联系人详情'"
      width="600px"
    >
      <div v-if="selectedContact" class="contact-detail">
        <div class="contact-header">
          <el-avatar :size="80">{{ selectedContact.name.charAt(0) }}</el-avatar>
          <div class="contact-info">
            <h3>{{ selectedContact.name }}</h3>
            <div class="contact-meta">
              <el-tag>{{ getDepartmentText(selectedContact.department) }}</el-tag>
              <span>{{ selectedContact.position }}</span>
            </div>
          </div>
        </div>
        <div class="contact-details">
          <div class="detail-item">
            <el-icon><Phone /></el-icon>
            <span class="label">电话：</span>
            <span class="value">{{ selectedContact.phone }}</span>
          </div>
          <div class="detail-item">
            <el-icon><Message /></el-icon>
            <span class="label">邮箱：</span>
            <span class="value">{{ selectedContact.email }}</span>
          </div>
          <div class="detail-item" v-if="selectedContact.remark">
            <el-icon><ChatDotRound /></el-icon>
            <span class="label">备注：</span>
            <span class="value">{{ selectedContact.remark }}</span>
          </div>
        </div>
        <div class="contact-actions">
          <el-button @click="editContact(selectedContact)">
            <el-icon><Edit /></el-icon> 编辑
          </el-button>
          <el-button type="primary" @click="callContact(selectedContact)">
            <el-icon><Phone /></el-icon> 拨打电话
          </el-button>
        </div>
      </div>
      <template #footer>
        <span class="dialog-footer">
          <el-button @click="viewContactVisible = false">关闭</el-button>
        </span>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import { Plus, Search, User, Phone, Message, ChatDotRound, Edit } from '@element-plus/icons-vue'
import api from '../api'

// 联系人数据
const contacts = ref([])
const departments = ref([])

const departmentFilter = ref('lab')
const searchKeyword = ref('')
const createContactVisible = ref(false)
const viewContactVisible = ref(false)
const selectedContact = ref(null)
const isEditing = ref(false)

const newContact = ref({
  name: '',
  department: 'lab',
  position: '',
  email: '',
  phone: '',
  remark: ''
})

// 加载数据
onMounted(async () => {
  try {
    // 加载部门数据
    const deptResponse = await api.getDepartments()
    departments.value = deptResponse.data
    
    // 加载用户数据
    const userResponse = await api.getUsers()
    contacts.value = userResponse.data.map(user => ({
      ...user,
      position: '员工' // 暂时设置为默认值
    }))
  } catch (error) {
    console.error('获取数据失败:', error)
  }
})

const filteredContacts = computed(() => {
  return contacts.value.filter(contact => {
    const departmentMatch = !departmentFilter.value || contact.department == departmentFilter.value
    const searchMatch = !searchKeyword.value || 
      contact.name.includes(searchKeyword.value) || 
      contact.email.includes(searchKeyword.value) ||
      contact.phone.includes(searchKeyword.value)
    return departmentMatch && searchMatch
  })
})

const getDepartmentText = (departmentId) => {
  if (departmentId === 'lab') return '实验室'
  const department = departments.value.find(dept => dept.id == departmentId)
  return department ? department.name : departmentId
}

const openCreateContactDialog = () => {
  isEditing.value = false
  newContact.value = {
    name: '',
    department: 'lab',
    position: '',
    email: '',
    phone: '',
    remark: ''
  }
  createContactVisible.value = true
}

const editContact = (contact) => {
  isEditing.value = true
  newContact.value = JSON.parse(JSON.stringify(contact))
  createContactVisible.value = true
}

const saveContact = () => {
  if (newContact.value.name && newContact.value.department && newContact.value.email && newContact.value.phone) {
    if (isEditing.value) {
      // 编辑现有联系人
      const index = contacts.value.findIndex(c => c.id === newContact.value.id)
      if (index !== -1) {
        contacts.value[index] = { ...newContact.value }
      }
    } else {
      // 创建新联系人
      const contact = {
        id: Date.now().toString(),
        ...newContact.value
      }
      contacts.value.push(contact)
    }
    createContactVisible.value = false
  }
}

const viewContact = (contact) => {
  selectedContact.value = JSON.parse(JSON.stringify(contact))
  viewContactVisible.value = true
}

const deleteContact = (id) => {
  // 删除联系人逻辑
  console.log('删除联系人:', id)
}

const callContact = (contact) => {
  // 拨打电话逻辑
  console.log('拨打电话:', contact.phone)
}
</script>

<style scoped>
.contacts-container {
  height: 100%;
  background-color: #fff;
  border-radius: 8px;
  padding: 20px;
  box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);
}

.contacts-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.contacts-header h2 {
  font-size: 20px;
  font-weight: 600;
  margin: 0;
}

.contacts-filter {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.filter-item {
  min-width: 150px;
}

.contacts-content {
  height: calc(100% - 120px);
  overflow-y: auto;
  position: relative;
}

.action-buttons {
  display: flex;
  gap: 8px;
  align-items: center;
}

.empty-table {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #999;
}

.empty-table .empty-icon {
  font-size: 48px;
  margin-bottom: 16px;
}

.contact-detail {
  padding: 10px 0;
}

.contact-header {
  display: flex;
  align-items: center;
  margin-bottom: 30px;
  padding-bottom: 20px;
  border-bottom: 1px solid #e6e6e6;
}

.contact-header .el-avatar {
  margin-right: 20px;
}

.contact-info h3 {
  margin: 0 0 8px 0;
  font-size: 20px;
  font-weight: 600;
}

.contact-meta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.contact-details {
  margin-bottom: 30px;
}

.detail-item {
  display: flex;
  align-items: center;
  margin-bottom: 16px;
  gap: 12px;
}

.detail-item .el-icon {
  color: #909399;
  width: 20px;
}

.detail-item .label {
  width: 60px;
  color: #909399;
  font-size: 14px;
}

.contact-actions {
  display: flex;
  gap: 12px;
}

.dialog-footer {
  width: 100%;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
</style>